3	/**
4	 * Normalizes a telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
5	 * form: a leading {@code '+'} followed by 8 to 15 digits.
6	 *
7	 * <p>Rules:
8	 * <ul>
9	 *   <li>spaces, dashes and brackets are stripped;</li>
10	 *   <li>when the input already carries a leading {@code '+'} (a country code), it is kept
11	 *       and the remaining digits are used verbatim;</li>
12	 *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
13	 *       dropped from the national digits;</li>
14	 *   <li>the result must have 8 to 15 digits after the {@code '+'}, else it is not valid E.164.</li>
15	 * </ul>
16	 *
17	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
18	 * becomes {@code "+6421123456"}.
19	 */
20	public final class TelephoneE164 {
21	
22	    private TelephoneE164() {
23	    }
24	
25	    /**
26	     * Returns the E.164 form of {@code raw}, or {@code null} if it cannot form a valid E.164
27	     * number.
28	     */
29	    public static String normalize(String raw) {
30	        if (raw == null) {
31	            return null;
32	        }
33	        boolean hasCountryCode = raw.strip().startsWith("+");
34	        String digits = raw.replaceAll("\\D", "");
35	        String e164Digits;
36	        if (hasCountryCode) {
37	            e164Digits = digits;
38	        }
39	        else {
40	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
41	            e164Digits = "61" + national;
42	        }
43	        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
44	            return null;
45	        }
46	        return "+" + e164Digits;
47	    }
48	}
