13	/**
14	 * Rejects a create-owner request that is missing or blank in any required field
15	 * ({@code firstName}, {@code lastName}, {@code address}, {@code city}, {@code telephone}).
16	 *
17	 * <p>Runs first in the {@code POST /api/owners} pipeline and binds the body without
18	 * {@code @Valid}, so a missing field surfaces as a {@link MissingOwnerFieldsException}
19	 * (400 with an {@code errors} array) rather than the generic schema-validation response.
20	 * The {@code address} is normalized first (see {@link AddressNormalizer}) so the blank
21	 * check rejects an address that is empty after normalization. It then normalizes the
22	 * telephone to E.164 form (see {@link TelephoneE164}), rejecting with an
23	 * {@link InvalidTelephoneException} (400) when it cannot form a valid E.164 number.
24	 * On success it stores the normalized address and E.164 telephone and republishes the
25	 * body for {@link BuildOwner}.
26	 */
27	public class ValidateOwnerFields {
28	
29	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
30	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
31	        List<String> errors = new ArrayList<>();
32	        String address = AddressNormalizer.normalize(request.getAddress());
33	        if (isBlank(request.getFirstName())) {
34	            errors.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            errors.add("lastName");
38	        }
39	        if (isBlank(address)) {
40	            errors.add("address");
41	        }
42	        if (isBlank(request.getCity())) {
43	            errors.add("city");
44	        }
45	        if (isBlank(request.getTelephone())) {
46	            errors.add("telephone");
47	        }
48	        if (!errors.isEmpty()) {
49	            throw new MissingOwnerFieldsException(errors);
50	        }
51	        request.setAddress(address);
52	        String telephone = TelephoneE164.normalize(request.getTelephone());
53	        if (telephone == null) {
54	            throw new InvalidTelephoneException(
55	                    "Telephone cannot be normalized to a valid E.164 number");
56	        }
57	        request.setTelephone(telephone);
58	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
59	        validated.set(request);
60	    }
61	
62	    private static boolean isBlank(String value) {
63	        return value == null || value.isBlank();
64	    }
65	}
