1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create-owner request whose normalized telephone is already used by any other
11	 * owner, responding 409 via {@link DuplicateTelephoneException}.
12	 *
13	 * <p>Runs after {@link ValidateOwnerFields} (which has already normalized the request's
14	 * telephone to E.164 form) and before {@link BuildOwner} saves anything. Each stored
15	 * owner's telephone is normalized to E.164 the same way before comparison, so equivalent
16	 * numbers written in different formats still collide.
17	 */
18	public class EnsureUniqueTelephone {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateTelephoneException {
22	        String telephone = normalize(request.getTelephone());
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (telephone.equals(normalize(existing.getTelephone()))) {
25	                throw new DuplicateTelephoneException(telephone);
26	            }
27	        }
28	    }
29	
30	    private static String normalize(String value) {
31	        String e164 = TelephoneE164.normalize(value);
32	        return e164 != null ? e164 : (value == null ? "" : value);
33	    }
34	}
